import{_ as a,o as t,c as r,ag as s}from"./chunks/framework.cyF4XceO.js";const m=JSON.parse('{"title":"Table Family proposals","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/table/index.md","filePath":"proposals/table/index.md"}'),o={name:"proposals/table/index.md"};function i(n,e,d,c,l,h){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="table-family-proposals" tabindex="-1">Table Family proposals <a class="header-anchor" href="#table-family-proposals" aria-label="Permalink to &quot;Table Family proposals&quot;">​</a></h1><p>The Table Family, <code>table.forms.takoform.com</code>, fixes the document/KV table shape — items addressed by a declared partition key — selected by <a href="./../../spec/decisions/0043-forms-target-popular-vendor-locked-primitives.html">decision 0043</a>. Its member preserves, completely, the application-visible semantics of that proven shape without naming its vendor (<a href="./../../spec/decisions/0008-forms-preserve-service-shape.html">decision 0008</a>).</p><h2 id="why-a-family-not-an-integration" tabindex="-1">Why a family, not an integration <a class="header-anchor" href="#why-a-family-not-an-integration" aria-label="Permalink to &quot;Why a family, not an integration&quot;">​</a></h2><p>A category with a de-facto standard API is never respecified as a Form; Takoform reaches it through a sealed standard-service slot instead (<a href="./../../spec/standard-services/">spec/standard-services</a>). The key-addressed table has no such standard: every major cloud offers one, each speaking only its own provisioning and data API, which is exactly the category decision 0043 assigns to a Form Family — the place where a host-neutral contract is the only portability there is. The document store that DOES have a standard wire, the Mongo-flavored one, sits on the integrate side of that decision&#39;s survey and is not this family. This family replaces the withdrawn v1alpha2 <code>KeyValueStore</code> and the key-addressed half of <code>StatefulEntity</code> (the addressable-actor half became the Edge family&#39;s <code>ActorNamespace</code> addition).</p><h2 id="authoring-policy-shape-preserving-contracts" tabindex="-1">Authoring policy: shape-preserving contracts <a class="header-anchor" href="#authoring-policy-shape-preserving-contracts" aria-label="Permalink to &quot;Authoring policy: shape-preserving contracts&quot;">​</a></h2><p>Every member Form preserves one service shape end to end: client API, data model, consistency, update and delete units, error semantics, and the capabilities exposed through typed Bindings. No free semantic token is admitted; a difference in semantics is a different Form, never a selector value. Outward capability use is a digest-bound Binding held by a revision resource; inward activation is an attachment resource (<a href="./../../spec/decisions/0010-exact-interface-and-binding-contracts.html">decision 0010</a>). Desired schemas carry no <code>name</code> or envelope plumbing: the resource envelope owns identity and status (<a href="./../../spec/decisions/0011-resource-identity-generation-and-revision.html">decision 0011</a>).</p><p>This prose accompanies the generated Experimental <code>Table</code> candidate under <code>forms/candidates/table.forms.takoform.com</code> and its exact <code>table.document</code> Interface. The generated candidate bytes, not this proposal, own the current identity. Family membership grants no maturity.</p><h2 id="current-members" tabindex="-1">Current members <a class="header-anchor" href="#current-members" aria-label="Permalink to &quot;Current members&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Form</th><th>Role</th><th>One-line semantics</th><th>Separate-Form boundary</th></tr></thead><tbody><tr><td><a href="./table.html">Table</a></td><td>identity</td><td>Key-addressed document table: declared partition/sort keys, atomic conditional writes, consistent single-item reads, key-ordered partition queries, declared secondary indexes, lazy TTL.</td><td>A cross-partition scan, an eventually-consistent-by-default table, or a query-language document store is not this Form.</td></tr></tbody></table><p>The family deliberately holds ONE Form. The key schema, secondary indexes, and TTL attribute are desired state of the <code>Table</code> because each declares which attributes address data — the identity&#39;s own addressing declaration — not an independently meaningful attachment or operating policy. A scan surface, a change feed, or a backup policy would be separate proposals when that work starts, per <a href="./../../spec/form-families.html">spec/form-families.md</a>.</p>',10)])])}const y=a(o,[["render",i]]);export{m as __pageData,y as default};
